const labelAttr = () => (driver.isAndroid ? 'content-desc' : 'label');
export const labelOf = async (el: WebdriverIO.Element) => String((await el.getAttribute(labelAttr()).catch(() => '')) ?? '');

/** Приложение на переднем плане (4 = RUNNING_IN_FOREGROUND). Крэш → 1 (не запущено) или 3 (фон). */
export async function appAlive(): Promise<boolean> {
  if (!appId()) return true;
  return (await driver.queryAppState(appId()).catch(() => 4)) === 4;
}
export async function expectAppAlive(where: string) {
  expect({ where, alive: await appAlive() }).toEqual({ where, alive: true });
}

// ───────────────────────── экран «תפילות» / «רשימת התפילות» (S-27) ─────────────────────────

export const PRAYERS_NUSACH_LINE = 'התפילות מוצגות בנוסח';   // «התפילות מוצגות בנוסח אשכנז שנשמר בפרופיל.»
export const LAST_CARD = 'שיעורי תורה';                      // последняя карточка списка (реджект 24.09, факт 14.10)

/** Признак открытого экрана «תפילות»: поле «חיפוש» + строка о нусахе; приложение живо. */
export async function waitPrayersScreen(where: string) {
  await driver.waitUntil(async () => {
    if (!(await appAlive())) throw new Error(`${where}: приложение закрылось (крэш) — регресс #70e8283a`);
    return (await shown(byLabel('חיפוש'))) && (await shown(byTextContains(PRAYERS_NUSACH_LINE)));
  }, { timeout: 20000, interval: 600, timeoutMsg: `${where}: экран «תפילות» не открылся` });
}

/** Вкладка «תפילות» (нижняя навигация — по тексту вкладки, не по координатам). */
export async function openPrayersTab() {
  await toHome();
  await goTab('תפילות');
  await waitPrayersScreen('вкладка «תפילות»');
}

/** Прокрутить список вниз до последней карточки «שיעורי תורה», проверяя, что приложение не упало на каждом шаге. */
export async function scrollPrayersToEnd(where: string) {
  for (let i = 0; i < 12; i++) {
    await expectAppAlive(`${where}, прокрутка ${i}`);
    if (await shown(byText(LAST_CARD))) return;
    await swipeUp();
  }
  throw new Error(`${where}: после прокрутки не видна последняя карточка «${LAST_CARD}»`);
}

/** Кнопка ☰ в шапке экрана молитвы — ТОЛЬКО по элементу (верх экрана, баннеры).
 *  TODO калибровка: точная подпись ☰ не записана 14.10 — пробуем известные варианты, затем «содержит תפריט». */
const MENU_LABELS = ['תפריט', 'פתיחת תפריט', 'פתיחת התפריט', 'תפריט התפילה', 'תפריט נוסף'];
export async function tapPrayerMenu() {
  for (const l of MENU_LABELS) {
    const el = await byLabel(l);
    if (await el.isDisplayed().catch(() => false)) { await el.click(); return; }
  }
  const any = driver.isAndroid
    ? await $('android=new UiSelector().descriptionContains("תפריט")')
    : await $('-ios predicate string:type == "XCUIElementTypeButton" AND (label CONTAINS "תפריט" OR name CONTAINS "תפריט")');
  if (await any.isDisplayed().catch(() => false)) { await any.click(); return; }
  throw new Error('Не найдена кнопка ☰ экрана молитвы по подписи (калибровка: снять page source, добавить label в MENU_LABELS)');
}

/** Экран молитвы → ☰ → «רשימת התפילות» → экран «תפילות». */
export async function openPrayersFromMenu() {
  await tapPrayerMenu();
  const item = await byText('רשימת התפילות');
  await item.waitForDisplayed({ timeout: 10000 });
  await item.click();
  await waitPrayersScreen('☰ → «רשימת התפילות»');
}

/** Поле поиска экрана «תפילות» (label «חיפוש», как в PC-01). */
export async function prayersSearchField() {
  const f = await byLabel('חיפוש');
  await f.waitForDisplayed({ timeout: 15000 });
  return f as unknown as WebdriverIO.Element;
}
export async function fieldValue(el: WebdriverIO.Element) {
  return driver.isAndroid ? await el.getText() : String((await el.getAttribute('value')) ?? '');
}
export async function fieldPlaceholder(el: WebdriverIO.Element) {
  if (driver.isAndroid) return String((await el.getAttribute('hint').catch(() => null)) ?? (await el.getText()));
  return String((await el.getAttribute('placeholderValue').catch(() => null)) ?? (await el.getAttribute('value').catch(() => '')) ?? '');
}

/** Карточка молитвы в каталоге (первый тап раскрывает время+колокольчик, второй — открывает). */
export async function prayerCard(title: string) {
  const el = driver.isAndroid
    ? await $(`android=new UiSelector().descriptionStartsWith("${title}").descriptionContains("נוסח התפילה")`)
    : await $(`-ios predicate string:(label BEGINSWITH "${title}, " OR label BEGINSWITH "פתיחת ${title}") AND label CONTAINS "נוסח התפילה"`);
  if (await el.isDisplayed().catch(() => false)) return el as unknown as WebdriverIO.Element;
  return (await byText(title)) as unknown as WebdriverIO.Element;
}

// ───────────────────────── скриншот: пиксели (полоса прокрутки) ─────────────────────────

export type Png = { width: number; height: number; channels: number; data: Buffer };

/** Минимальный декодер PNG (8 бит, RGB/RGBA, без interlace) — скриншоты Appium именно такие. */
export function decodePng(b64: string): Png {
  const buf = Buffer.from(b64, 'base64');
  let off = 8; let width = 0; let height = 0; let colorType = 0; let depth = 0; let interlace = 0;
  const idat: Buffer[] = [];
  while (off < buf.length) {
    const len = buf.readUInt32BE(off); const type = buf.toString('ascii', off + 4, off + 8);
    const chunk = buf.subarray(off + 8, off + 8 + len);
    if (type === 'IHDR') { width = chunk.readUInt32BE(0); height = chunk.readUInt32BE(4); depth = chunk[8]; colorType = chunk[9]; interlace = chunk[12]; }
    else if (type === 'IDAT') idat.push(chunk);
    else if (type === 'IEND') break;
    off += 12 + len;
  }
  if (depth !== 8 || interlace !== 0 || ![2, 6].includes(colorType)) throw new Error(`PNG не поддержан: depth=${depth} color=${colorType} interlace=${interlace}`);
  const channels = colorType === 6 ? 4 : 3;
  const raw = inflateSync(Buffer.concat(idat));
  const stride = width * channels;
  const out = Buffer.alloc(height * stride);
  for (let y = 0; y < height; y++) {
    const f = raw[y * (stride + 1)];
    const line = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1));
    for (let x = 0; x < stride; x++) {
      const a = x >= channels ? out[y * stride + x - channels] : 0;
      const b = y > 0 ? out[(y - 1) * stride + x] : 0;
      const c = x >= channels && y > 0 ? out[(y - 1) * stride + x - channels] : 0;
      let v = line[x];
      if (f === 1) v += a;
      else if (f === 2) v += b;
      else if (f === 3) v += (a + b) >> 1;
      else if (f === 4) { const p = a + b - c; const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c; }
      out[y * stride + x] = v & 0xff;
    }
  }
  return { width, height, channels, data: out };
}

/** Золотой цвет приложения (факт 14.10: полоса и акценты ≈ rgb(217,168,95)). */
export const isGold = (r: number, g: number, b: number) => r >= 180 && g >= 125 && g <= 200 && b <= 140 && r - b >= 70;

/** Сколько строк пикселей с золотым в вертикальной полосе экрана [x0..x1) × [y0..y1) (координаты — в точках экрана). */
export async function goldRowsInStrip(x0: number, x1: number, y0: number, y1: number): Promise<number> {
  const png = decodePng(await driver.takeScreenshot());
  const { width: ww } = await driver.getWindowSize();
  const k = png.width / ww;
  let rows = 0;
  for (let y = Math.round(y0 * k); y < Math.min(png.height, Math.round(y1 * k)); y++) {
    for (let x = Math.round(x0 * k); x < Math.min(png.width, Math.round(x1 * k)); x++) {
      const i = (y * png.width + x) * png.channels;
      if (isGold(png.data[i], png.data[i + 1], png.data[i + 2])) { rows++; break; }
    }
  }
  return Math.round(rows / k);
}

// ───────────────────────── геометрия текста ─────────────────────────

/** Видимые StaticText (iOS) / TextView (Android) с рамкой — для проверки выравнивания и наложения строк. */
export async function visibleTexts(filter?: (label: string, r: Rect) => boolean) {
  const els = driver.isAndroid
    ? await $$('android=new UiSelector().className("android.widget.TextView")').getElements()
    : await $$('-ios predicate string:type == "XCUIElementTypeStaticText" AND visible == 1').getElements();
  const out: { label: string; r: Rect }[] = [];
  for (const el of els) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const label = (await el.getText().catch(() => '')) || (await labelOf(el));
    const r = await rectOf(el);
    if (!filter || filter(label, r)) out.push({ label, r });
  }
  return out;
}

// ───────────────────────── «תאריכים חשובים»: временная запись ─────────────────────────

/** Создать «תאריך חשוב» на сегодня (iso YYYY-MM-DD) с именем name. */
export async function addImportantDateToday(name: string, iso: string) {
  await homeDates();
  await tapLabel('הוספת תאריך חשוב');
  await tapText('תאריך חשוב');
  const field = await dateNameField();
  await field.setValue(name);
  const day = await byLabelStartsWith(`${iso}, `);
  await day.waitForDisplayed({ timeout: 15000 });
  await day.click();
  await tapText('הוסף תאריך');
  await expect(byText('הוסף תאריך')).not.toBeDisplayed({ wait: 10000 });
  await homeDates();
  return scrollToDateCard(name);
}

/** Текст окна подтверждения удаления (ID-02 web, #7b04425b; факт iOS 14.10). */
export const DELETE_TITLE = 'למחוק את התאריך?';
export const deleteBody = (name: string) => `«${name}» יימחק מהתאריכים החשובים שלך, ואי אפשר יהיה לשחזר אותו.`;

/** Карандаш записи (label «<имя>: פתיחה לעריכה») → «עריכת תאריך» → «מחיקת התאריך» → окно подтверждения. */
export async function openDeleteDialog(name: string) {
  await (await scrollToDateCard(name)).click();
  await (await byText('עריכת תאריך')).waitForDisplayed({ timeout: 15000 });
  const del = await byLabel('מחיקת התאריך');
  const target = (await del.isExisting().catch(() => false)) ? del : await byText('מחיקת התאריך');
  for (let i = 0; i < 4 && !(await target.isDisplayed().catch(() => false)); i++) await swipeUp();
  await target.click();
  await (await byText(DELETE_TITLE)).waitForDisplayed({ timeout: 10000 });
}

/** Запись есть в списке (кнопка «<имя>: פתיחה לעריכה» существует после прокрутки). */
export async function dateExists(name: string): Promise<boolean> {
  await toHome();
  await homeDates();
  const el = await byLabel(`${name}: פתיחה לעריכה`);
  for (let i = 0; i < 6 && !(await el.isDisplayed().catch(() => false)); i++) await swipeUp();
  return el.isDisplayed().catch(() => false);
}
